options.styles:
.project-kanban {
  color: var(--grafana-color-text-primary, inherit);
  width: 100%;
}
.project-kanban__columns {
  display: flex;
  align-items: stretch;
  gap: 12px;
  overflow-x: auto;
  padding: 4px 2px 12px;
  scrollbar-width: thin;
}
.project-kanban__column {
  flex: 1 0 245px;
  min-width: 0;
  border: 1px solid var(--grafana-color-border-weak, rgba(128,128,128,.28));
  border-radius: 8px;
  background: var(--grafana-color-background-secondary, rgba(128,128,128,.06));
}
.project-kanban__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 12px;
  border-bottom: 1px solid var(--grafana-color-border-weak, rgba(128,128,128,.28));
}
.project-kanban__title {
  overflow: hidden;
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.project-kanban__count {
  flex: 0 0 auto;
  min-width: 24px;
  padding: 2px 7px;
  border-radius: 12px;
  background: var(--grafana-color-background-primary, rgba(128,128,128,.12));
  text-align: center;
  font-size: 12px;
}
.project-kanban__cards {
  display: grid;
  gap: 8px;
  max-height: 380px;
  overflow-y: auto;
  padding: 10px;
}
.project-kanban__card {
  padding: 11px;
  border: 1px solid var(--grafana-color-border-weak, rgba(128,128,128,.22));
  border-radius: 6px;
  background: var(--grafana-color-background-primary, transparent);
}
.project-kanban__name {
  margin: 3px 0 10px;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.4;
  overflow-wrap: anywhere;
}
.project-kanban__id,
.project-kanban__meta {
  color: var(--grafana-color-text-secondary, #888);
  font-size: 11px;
}
.project-kanban__meta {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  margin-bottom: 8px;
}
.project-kanban__progress-label {
  display: flex;
  justify-content: space-between;
  margin-bottom: 4px;
  font-size: 11px;
}
.project-kanban__progress {
  width: 100%;
  height: 5px;
  overflow: hidden;
  border-radius: 4px;
  background: var(--grafana-color-border-weak, rgba(128,128,128,.25));
}
.project-kanban__progress > span {
  display: block;
  height: 100%;
  background: var(--grafana-color-text-link, #5794f2);
}
.project-kanban__empty {
  padding: 8px 2px;
  color: var(--grafana-color-text-secondary, #888);
  font-size: 12px;
}

options.helpers:
// Build safe, escaped card markup from the SQL data frame.
context.handlebars.registerHelper('renderKanban', (rows) => {
  const escapeHtml = (value) => String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
  const values = Array.isArray(rows) ? rows : [];
  const columns = new Map();

  for (const row of values) {
    const key = String(row.state_id ?? '');
    if (!columns.has(key)) {
      columns.set(key, { name: row.state_name || 'Sem estado', projects: [] });
    }
    if (row.project_id !== null && row.project_id !== undefined) {
      columns.get(key).projects.push(row);
    }
  }

  return [...columns.values()].map((column) => {
    const cards = column.projects.length
      ? column.projects.map((project) => {
          const progress = Math.max(0, Math.min(100, Number(project.percent_done) || 0));
          return `<article class="project-kanban__card">
            <div class="project-kanban__id">#${escapeHtml(project.project_id)}</div>
            <h3 class="project-kanban__name">${escapeHtml(project.project_name)}</h3>
            <div class="project-kanban__meta"><span>Prioridade ${escapeHtml(project.priority)}</span><span>${escapeHtml(project.task_count)} tarefas</span></div>
            <div class="project-kanban__progress-label"><span>Progresso</span><span>${progress.toFixed(0)}%</span></div>
            <div class="project-kanban__progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><span style="width:${progress}%"></span></div>
          </article>`;
        }).join('')
      : '<div class="project-kanban__empty">Nenhum projeto</div>';
    return `<section class="project-kanban__column"><header class="project-kanban__header"><h2 class="project-kanban__title">${escapeHtml(column.name)}</h2><span class="project-kanban__count">${column.projects.length}</span></header><div class="project-kanban__cards">${cards}</div></section>`;
  }).join('');
});
